// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PromotionChannel) predicate.PromotionChannel {
	return predicate.PromotionChannel(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PromotionChannel) predicate.PromotionChannel {
	return predicate.PromotionChannel(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PromotionChannel) predicate.PromotionChannel {
	return predicate.PromotionChannel(sql.NotPredicates(p))
}
